/**
 * Test flow for createRecord action
 * Demonstrates creating a new record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testCreateRecord = Flow(
    {
        $id: Now.ID['test_create_record_flow'],
        name: 'Test Create Record',
        description: 'Tests the createRecord core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_create_record_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=received',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_create_record_action'] },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: `${wfa.dataPill(_params.trigger.current.subject, 'string')}`,
                    description: `${wfa.dataPill(_params.trigger.current.body_text, 'string')}`,
                    priority: 3,
                }),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_create_record_log'] },
            {
                log_level: 'info',
                log_message: `createRecord outputs: record=${wfa.dataPill(result.record, 'reference')}, table_name=${wfa.dataPill(result.table_name, 'string')}`,
            }
        )
    }
)
